namespace Zeal {
namespace Util {

struct CaseInsensitiveStringComparator
{
    bool operator()(const QString &lhs, const QString &rhs) const
    {
        return QString::compare(lhs, rhs, Qt::CaseInsensitive) < 0;
    }
};

} // namespace Util
} // namespace Zeal

