namespace Util {

class Humanizer
{
    Q_DECLARE_TR_FUNCTIONS(Humanizer)
    Q_DISABLE_COPY_MOVE(Humanizer)
    Humanizer() = delete;
    ~Humanizer() = delete;
public:
    static QString fromNow(const QDateTime& dt);
};

} // namespace Util
} // namespace Zeal

namespace Zeal {
namespace Util {

class Plist : public QHash<QString, QVariant>
{
public:
    Plist() = default;

    bool read(const QString &fileName);
    bool hasError() const;

private:
    bool m_hasError = false;
};

} // namespace Util
} // namespace Zeal

class SQLiteDatabase
{
    Q_DISABLE_COPY_MOVE(SQLiteDatabase)
public:
    explicit SQLiteDatabase(const QString &path);
    virtual ~SQLiteDatabase();

    bool isOpen() const;

    QStringList tables();
    QStringList views();

    bool prepare(const QString &sql);
    bool next();

    bool execute(const QString &sql);

    QVariant value(int index) const;

    QString lastError() const;

    sqlite3 *handle() const;

private:
    void close();
    void finalize();
    void updateLastError();

    sqlite3 *m_db = nullptr;
    sqlite3_stmt *m_stmt = nullptr;
    QString m_lastError;
};

